// TaskServiceHandler is an implementation of the flowsk.task.v1.TaskService service.
type TaskServiceHandler interface {
	// CreateTask mints a new sequential identifier (e.g., "FLW-42") and creates a task.
	CreateTask(context.Context, *connect.Request[v1.CreateTaskRequest]) (*connect.Response[v1.CreateTaskResponse], error)
	// GetTask retrieves full task details and its immediate dependency relations by UUID.
	GetTask(context.Context, *connect.Request[v1.GetTaskRequest]) (*connect.Response[v1.GetTaskResponse], error)
	// GetTaskByIdentifier retrieves full task details using its compact key (e.g., "FLW-42").
	GetTaskByIdentifier(context.Context, *connect.Request[v1.GetTaskByIdentifierRequest]) (*connect.Response[v1.GetTaskByIdentifierResponse], error)
	// GetTaskByExternalId retrieves full task details inside a project using its external tracker ID (e.g., "CU-869abc").
	GetTaskByExternalId(context.Context, *connect.Request[v1.GetTaskByExternalIdRequest]) (*connect.Response[v1.GetTaskByExternalIdResponse], error)
	// ListTasks searches and filters tasks within a workspace or project with pagination.
	ListTasks(context.Context, *connect.Request[v1.ListTasksRequest]) (*connect.Response[v1.ListTasksResponse], error)
	// UpdateTask modifies mutable task metadata, hierarchy links, assignee, or labels.
	UpdateTask(context.Context, *connect.Request[v1.UpdateTaskRequest]) (*connect.Response[v1.UpdateTaskResponse], error)
	// TransitionTaskState moves a task to a target workflow state and optionally
	// records a resolution note in a single atomic transaction.
	TransitionTaskState(context.Context, *connect.Request[v1.TransitionTaskStateRequest]) (*connect.Response[v1.TransitionTaskStateResponse], error)
	// ClaimTask atomically acquires or renews a time-bounded execution lease on a task
	// for the calling actor, preventing duplicate concurrent work by multiple agents.
	ClaimTask(context.Context, *connect.Request[v1.ClaimTaskRequest]) (*connect.Response[v1.ClaimTaskResponse], error)
	// ReleaseTaskClaim relinquishes an active lease on a task and optionally posts
	// a structured TASK_COMMENT_KIND_HANDOFF comment for the next actor.
	ReleaseTaskClaim(context.Context, *connect.Request[v1.ReleaseTaskClaimRequest]) (*connect.Response[v1.ReleaseTaskClaimResponse], error)
	// AddTaskRelation creates a directed dependency link (BLOCKS, DUPLICATES, RELATES_TO)
	// between two tasks in the workspace, rejecting self-loops.
	AddTaskRelation(context.Context, *connect.Request[v1.AddTaskRelationRequest]) (*connect.Response[v1.AddTaskRelationResponse], error)
	// RemoveTaskRelation deletes an existing task relation edge by UUID.
	RemoveTaskRelation(context.Context, *connect.Request[v1.RemoveTaskRelationRequest]) (*connect.Response[v1.RemoveTaskRelationResponse], error)
	// AddTaskComment appends a typed comment, blocker report, handoff, or resolution to a task.
	AddTaskComment(context.Context, *connect.Request[v1.AddTaskCommentRequest]) (*connect.Response[v1.AddTaskCommentResponse], error)
	// ListTaskComments lists timeline comments on a task ordered chronologically.
	ListTaskComments(context.Context, *connect.Request[v1.ListTaskCommentsRequest]) (*connect.Response[v1.ListTaskCommentsResponse], error)
	// GetAgentWorkQueue returns prioritized, unblocked, unclaimed tasks ready for
	// immediate autonomous execution alongside tasks already leased by the caller.
	GetAgentWorkQueue(context.Context, *connect.Request[v1.GetAgentWorkQueueRequest]) (*connect.Response[v1.GetAgentWorkQueueResponse], error)
	// GetProjectDigest computes a compact health and priority digest for a single project.
	GetProjectDigest(context.Context, *connect.Request[v1.GetProjectDigestRequest]) (*connect.Response[v1.GetProjectDigestResponse], error)
	// DeleteTask permanently deletes a task and its attached relations and comments.
	DeleteTask(context.Context, *connect.Request[v1.DeleteTaskRequest]) (*connect.Response[v1.DeleteTaskResponse], error)
	// GetTaskMarkdown retrieves the optional extended Markdown document (`<task_id>.md`)
	// associated with a task in Flowsk's global storage directory.
	GetTaskMarkdown(context.Context, *connect.Request[v1.GetTaskMarkdownRequest]) (*connect.Response[v1.GetTaskMarkdownResponse], error)
	// PutTaskMarkdown creates or updates the extended Markdown document (`<task_id>.md`)
	// associated with a task and marks has_markdown_doc true.
	PutTaskMarkdown(context.Context, *connect.Request[v1.PutTaskMarkdownRequest]) (*connect.Response[v1.PutTaskMarkdownResponse], error)
	// DeleteTaskMarkdown deletes the extended Markdown document (`<task_id>.md`)
	// associated with a task and marks has_markdown_doc false.
	DeleteTaskMarkdown(context.Context, *connect.Request[v1.DeleteTaskMarkdownRequest]) (*connect.Response[v1.DeleteTaskMarkdownResponse], error)
	// PurgeArchivedTasks permanently deletes all tasks in the ARCHIVED state across
	// the workspace and removes their associated `.md` resource files.
	PurgeArchivedTasks(context.Context, *connect.Request[v1.PurgeArchivedTasksRequest]) (*connect.Response[v1.PurgeArchivedTasksResponse], error)
	// InspectOrphanResources scans the workspace for `.md` files without an active
	// DB record and DB records marked has_markdown_doc whose `.md` file is missing.
	InspectOrphanResources(context.Context, *connect.Request[v1.InspectOrphanResourcesRequest]) (*connect.Response[v1.InspectOrphanResourcesResponse], error)
	// PruneOrphanResources cleans up orphan `.md` files and clears broken DB
	// has_markdown_doc flags across the workspace (supporting dry_run previews).
	PruneOrphanResources(context.Context, *connect.Request[v1.PruneOrphanResourcesRequest]) (*connect.Response[v1.PruneOrphanResourcesResponse], error)
}

